# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COĞRAFİ BİLGİ SİSTEMLERİ (CBS) VE KATMANLI VERİ MİMARİSİ</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">CBS\'nin 5 Temel Bileşeni</text>\n  <text x="40" y="103" font-size="11" fill="#334155">1. Donanım (Sunucu, GPS, İHA)</text>\n  <text x="40" y="125" font-size="11" fill="#334155">2. Yazılım (Masaüstü &amp; Web-CBS)</text>\n  <text x="40" y="147" font-size="11" fill="#334155">3. Veri (Mekânsal &amp; Öznitelik)</text>\n  <text x="40" y="169" font-size="11" fill="#334155">4. İnsan (Analist ve Kullanıcı)</text>\n  <text x="40" y="191" font-size="11" fill="#334155">5. Yöntem (Analiz Algoritmaları)</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Vektör ve Raster Veri Modeli</text>\n  <text x="262" y="103" font-size="11" font-weight="bold" fill="#166534">• Vektör Veri (Koordinatlı):</text>\n  <text x="270" y="120" font-size="10.5" fill="#475569">- Nokta: Kuyu, okul, deprem merkezi</text>\n  <text x="270" y="137" font-size="10.5" fill="#475569">- Çizgi: Akarsu, kara yolu, fay hattı</text>\n  <text x="270" y="154" font-size="10.5" fill="#475569">- Poligon (Alan): Göl, il sınırı, orman</text>\n  <text x="262" y="178" font-size="11" font-weight="bold" fill="#166534">• Raster Veri (Hücre / Piksel):</text>\n  <text x="270" y="195" font-size="10.5" fill="#475569">Uydu görüntüsü, hava fotoğrafı,</text>\n  <text x="270" y="211" font-size="10.5" fill="#475569">sayısal yükselti modeli (SYM/DEM).</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Katmanlı (Layer) Çakıştırma</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Katman 1: İdari Sınırlar ve Nüfus</text>\n  <text x="485" y="125" font-size="11" fill="#334155">• Katman 2: Ulaşım ve Altyapı Ağı</text>\n  <text x="485" y="147" font-size="11" fill="#334155">• Katman 3: Hidrografya ve Eğim</text>\n  <text x="485" y="169" font-size="11" fill="#334155">• Katman 4: Arazi Kullanımı</text>\n  <text x="572" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Üst üste çakıştırma (Overlay) ile</text>\n  <text x="572" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">sentez ve uygun yer seçimi yapılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">WEB TABANLI CBS (WEB-CBS) MİMARİSİ VE MEKÂNSAL ANALİZLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Web-CBS Çalışma Prensibi</text>\n  <text x="50" y="105" font-size="11" fill="#334155">• Bulut Sunucu + Harita Servisleri (WMS, WFS)</text>\n  <text x="50" y="127" font-size="11" fill="#334155">• Kurulum gerektirmeden internet tarayıcısı</text>\n  <text x="60" y="145" font-size="10.5" fill="#475569">veya mobil cihaz üzerinden erişim sağlar.</text>\n  <text x="50" y="170" font-size="11" fill="#334155">• Gerçek zamanlı (anlık) veri paylaşımı: Trafik,</text>\n  <text x="60" y="188" font-size="10.5" fill="#475569">meteoroloji, deprem, orman yangını izleme.</text>\n  <text x="185" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Örnek: Atlas Uygulaması, TKGM Parsel, AFAD</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Temel CBS Mekânsal Analiz Türleri</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Tampon Bölge (Buffer) Analizi: Fay hattı veya</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">akarsu çevresinde belirli mesafe koruma kuşağı.</text>\n  <text x="380" y="142" font-size="11" fill="#334155">• Çakıştırma (Overlay) Analizi: Farklı katmanları</text>\n  <text x="390" y="159" font-size="10.5" fill="#475569">birleştirerek en uygun yer seçimi (okul, santral).</text>\n  <text x="380" y="181" font-size="11" fill="#334155">• Ağ (Network) Analizi: En kısa ve en hızlı</text>\n  <text x="390" y="198" font-size="10.5" fill="#475569">ulaşım/ambulans rotasının hesaplanması.</text>\n  <text x="380" y="218" font-size="11" fill="#334155">• Yüzey Analizi: Eğim, bakı ve görünürlük.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">WEB-CBS İLE HARİTA OLUŞTURMA ADIMLARI (COĞ.11.2.1)</text>\n  <rect x="25" y="55" width="150" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="100" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Amaç ve Altlık</text>\n  <text x="38" y="110" font-size="10.5" fill="#334155">• Harita konusu seçilir.</text>\n  <text x="38" y="130" font-size="10.5" fill="#334155">• Uygun altlık harita</text>\n  <text x="45" y="146" font-size="10" fill="#475569">(topoğrafya, uydu veya</text>\n  <text x="45" y="162" font-size="10" fill="#475569">sokak haritası) açılır.</text>\n  <rect x="190" y="55" width="150" height="170" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="265" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Katman Ekleme</text>\n  <text x="203" y="110" font-size="10.5" fill="#334155">• Nokta, çizgi, poligon</text>\n  <text x="210" y="126" font-size="10" fill="#475569">katmanları eklenir.</text>\n  <text x="203" y="148" font-size="10.5" fill="#334155">• Öznitelik tablosuna</text>\n  <text x="210" y="164" font-size="10" fill="#475569">sayısal veriler girilir.</text>\n  <rect x="355" y="55" width="150" height="170" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="430" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. Sembol ve Analiz</text>\n  <text x="368" y="110" font-size="10.5" fill="#334155">• Renk derecelendirme</text>\n  <text x="375" y="126" font-size="10" fill="#475569">(koroplet) ve sembol</text>\n  <text x="375" y="142" font-size="10" fill="#475569">boyutu ayarlanır.</text>\n  <text x="368" y="164" font-size="10.5" fill="#334155">• Sorgulama yapılır.</text>\n  <rect x="520" y="55" width="155" height="170" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="597" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">4. Çıkarım ve Paylaşım</text>\n  <text x="533" y="110" font-size="10.5" fill="#334155">• Lejant, ölçek, yön</text>\n  <text x="540" y="126" font-size="10" fill="#475569">oku ve başlık eklenir.</text>\n  <text x="533" y="148" font-size="10.5" fill="#334155">• Mekânsal dağılış</text>\n  <text x="540" y="164" font-size="10" fill="#475569">yorumlanıp paylaşılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
